const localDateKey=d=>{const x=d instanceof Date?d:new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const localDateTime=d=>{if(!d)return '—';try{const dt=new Date(d);const tz=Intl.DateTimeFormat().resolvedOptions().timeZone||undefined;const locale=navigator.language||'ar-SY';return new Intl.DateTimeFormat(locale,{dateStyle:'medium',timeStyle:'short',hour12:false,timeZone:tz}).format(dt)}catch{return new Date(d).toLocaleString()}};
function useUsbBarcodeCapture(enabled,onCode){
 const callbackRef=useRef(onCode); const bufferRef=useRef(''); const lastRef=useRef(0); const timerRef=useRef(null);
 useEffect(()=>{callbackRef.current=onCode},[onCode]);
 useEffect(()=>{
  if(!enabled)return;
  const reset=()=>{bufferRef.current='';lastRef.current=0;if(timerRef.current){clearTimeout(timerRef.current);timerRef.current=null}};
  const onKey=e=>{
   const target=e.target; const tag=(target?.tagName||'').toUpperCase();
   const isEditable=tag==='TEXTAREA'||target?.isContentEditable;
   const now=Date.now();
   if(e.key==='Enter'){
    const rapid=now-lastRef.current<=220;
    const targetValue=tag==='INPUT'&&typeof target.value==='string'?target.value.trim():'';
    const code=(bufferRef.current||targetValue).trim();
    if(code.length>=4 && (rapid || bufferRef.current.length>=4)){
      if(!isEditable){e.preventDefault()}
      reset();
      callbackRef.current?.(code);
    }
    return;
   }
   if(typeof e.key!=='string'||e.key.length!==1)return;
   if(tag==='TEXTAREA'||target?.isContentEditable)return;
   if(now-lastRef.current>90)bufferRef.current=e.key; else bufferRef.current+=e.key;
   lastRef.current=now;
   if(timerRef.current)clearTimeout(timerRef.current);
   timerRef.current=setTimeout(reset,260);
  };
  window.addEventListener('keydown',onKey,true);
  return()=>{window.removeEventListener('keydown',onKey,true);reset()};
 },[enabled]);
}

const readCart=()=>{try{const v=JSON.parse(localStorage.getItem('pharma_cart')||'[]');return Array.isArray(v)?v.filter(x=>x&&x.id):[]}catch{return[]}};
const writeCart=v=>{try{localStorage.setItem('pharma_cart',JSON.stringify(v));}catch(e){console.warn('cart storage',e)}};
const POS_DRAFT_KEY='pharma_pos_draft_v1';
const readPosDraft=()=>{try{const v=JSON.parse(localStorage.getItem(POS_DRAFT_KEY)||'null');return v&&typeof v==='object'&&Array.isArray(v.cart)?v:null}catch{return null}};
const writePosDraft=v=>{try{localStorage.setItem(POS_DRAFT_KEY,JSON.stringify(v))}catch(e){console.warn('pos draft storage',e)}};
const clearPosDraft=()=>{try{localStorage.removeItem(POS_DRAFT_KEY)}catch(e){console.warn('pos draft clear',e)}};
function App(){const [session,setSession]=useState(null); const [admin,setAdmin]=useState(false); const [loading,setLoading]=useState(true);
 useEffect(()=>{if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{})}},[]);
 useEffect(()=>{if(!supabase){setLoading(false);return} supabase.auth.getSession().then(({data})=>{setSession(data.session);setAdmin(data.session?.user?.app_metadata?.role==='admin');setLoading(false)}); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>{setSession(s);setAdmin(s?.user?.app_metadata?.role==='admin')});return()=>subscription.unsubscribe()},[]);
 if(loading)return <Splash/>; if(!supabase)return <ConfigError/>; return admin?<Admin onLogout={()=>supabase.auth.signOut()}/>:<Customer session={session}/>}

class AppErrorBoundary extends React.Component {
  constructor(props){super(props);this.state={error:null}}
  static getDerivedStateFromError(error){return {error}}
  componentDidCatch(error,info){console.error('Pharmacy UI error',error,info)}
  render(){
    if(this.state.error) return <div className="center" dir="rtl"><h1>حدث خطأ في واجهة الصيدلية</h1><p>السلة أو إحدى الواجهات واجهت خطأ غير متوقع.</p><button className="primary" onClick={()=>this.setState({error:null})}>إعادة المحاولة</button><small style={{display:'block',marginTop:12,opacity:.7}}>{this.state.error?.message||'Unknown error'}</small></div>;
    return this.props.children;
  }
}

