function Prescriptions(){const [rows,setRows]=useState([]),[file,setFile]=useState(null),[busy,setBusy]=useState(false),[detail,setDetail]=useState(null);const load=async()=>{const {data,error}=await supabase.from('prescriptions').select('*').order('created_at',{ascending:false}).limit(150);if(error)throw error;setRows(data||[])};useEffect(()=>{load().catch(console.warn)},[]);const upload=async()=>{if(!file)return alert('اختر ملفاً');setBusy(true);try{const {data:{user}}=await supabase.auth.getUser();const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`admin/${crypto.randomUUID()}-${safe}`;let r=await supabase.storage.from('prescriptions').upload(path,file,{contentType:file.type});if(r.error)throw r.error;r=await supabase.from('prescriptions').insert({file_path:path,file_name:file.name,mime_type:file.type,file_size:file.size,created_by:user.id,status:'new'});if(r.error)throw r.error;setFile(null);await load();alert('تم رفع الوصفة')}catch(e){alert(e.message)}finally{setBusy(false)}};const view=async p=>{const {data,error}=await supabase.storage.from('prescriptions').createSignedUrl(p,300);if(error)alert(error.message);else window.open(data.signedUrl,'_blank','noopener,noreferrer')};const status=async(id,s)=>{const {error}=await supabase.from('prescriptions').update({status:s}).eq('id',id);if(error)alert(error.message);else load()};const labels={new:'جديدة',reviewing:'قيد المراجعة',ready:'تم تجهيزها',completed:'تم التسليم',rejected:'مرفوضة'};return <><PageHead title="الوصفات الطبية" sub="وصفات العملاء مع دورة مراجعة واضحة" refresh={load}/><div className="upload card"><input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" onChange={e=>setFile(e.target.files?.[0]||null)}/><button className="primary" onClick={upload} disabled={!file||busy}><Upload/> رفع وصفة إدارية</button></div><div className="tableWrap"><table><thead><tr><th>العميل</th><th>الهاتف</th><th>الملف</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.customer_name||'—'}</td><td>{r.customer_phone||'—'}</td><td>{r.file_name||'—'}</td><td><select value={r.status||'new'} onChange={e=>status(r.id,e.target.value)}>{Object.entries(labels).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></td><td>{localDateTime(r.created_at)}</td><td><button className="iconBtn" onClick={()=>view(r.file_path)}><Eye/></button></td></tr>)}</tbody></table></div></>}
